INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190801, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 0, 1, 2, 1, 1000001, 1, "カリン", "2025/01/31 12:00:00", 62, 3.414, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190801, "ミッションをクリアして、\n報酬をゲットしましょう！", 0, 2, 2, 1, 1000002, 1, "カリン", "2025/01/31 12:00:00", 62, 3.099, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190801, "受け取ることができる\n報酬があるようです\n確認してみてください", 0, 3, 2, 1, 1000003, 1, "カリン", "2025/01/31 12:00:00", 63, 2.801, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190801, "報酬がもらえますよ！\nチェックしてみてください", 0, 4, 2, 2, 1000004, 1, "カリン", "2025/01/31 12:00:00", 63, 0, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190801, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 0, 5, 1, 2, 1000005, 1, "カリン", "2025/01/31 12:00:00", 64, 2.12, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190801, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 0, 6, 2, 1, 1000006, 1, "カリン", "2025/01/31 12:00:00", 64, 1.68, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190801, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 0, 7, 1, 2, 1000007, 1, "カリン", "2025/01/31 12:00:00", 64, 2.33, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 133701, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", -6, 101, 7, 3, 1020101, 10201, "ラビリスタ", "2025/01/31 12:00:00", 61, 5.18, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 133901, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", -2, 201, 2, 1, 1020102, 10201, "クリスティーナ", "2025/01/31 12:00:00", 61, 8.77, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 133801, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 0, 301, 1, 6, 1020103, 10201, "ネネカ", "2025/01/31 12:00:00", 61, 15.5, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 134301, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 0, 101, 5, 2, 1020201, 10202, "ランファ", "2025/02/28 12:00:00", 61, 9.061, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 134401, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 0, 201, 2, 1, 1020202, 10202, "チカ", "2025/02/28 12:00:00", 61, 7.699, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 134601, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 0, 101, 2, 1, 1020301, 10203, "アオイ", "2025/03/31 12:00:00", 61, 8.595, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 134501, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 0, 201, 2, 1, 1020302, 10203, "クローチェ", "2025/03/31 12:00:00", 61, 7.758, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 132302, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 0, 101, 6, 2, 1020401, 10204, "ルイズマリー", "2025/04/30 12:00:00", 61, 7, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 132402, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 0, 201, 2, 1, 1020402, 10204, "イロハ", "2025/04/30 12:00:00", 61, 7.904, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 132502, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 0, 301, 2, 4, 1020403, 10204, "ソノ", "2025/04/30 12:00:00", 61, 8.487, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 134901, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 0, 101, 2, 1, 1020502, 10205, "カノン", "2025/05/31 12:00:00", 61, 8.763, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 134801, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 0, 201, 3, 1, 1020503, 10205, "ツムギ", "2025/05/31 12:00:00", 61, 6.417, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 135001, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 0, 101, 7, 3, 1020601, 10206, "エリス", "2025/06/30 12:00:00", 61, 10.335, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 135101, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 0, 201, 4, 2, 1020602, 10206, "シェフィ", "2025/06/30 12:00:00", 61, 6.281, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 135201, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 0, 301, 2, 1, 1020603, 10206, "プレシア", "2025/06/30 12:00:00", 61, 12.244, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 135301, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 0, 101, 8, 2, 1020701, 10207, "クリア", "2025/07/31 12:00:00", 61, 6.339, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 135401, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 0, 201, 9, 7, 1020702, 10207, "アネモネ", "2025/07/31 12:00:00", 61, 8.184, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 129101, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 0, 101, 2, 9, 1020801, 10208, "アイラ", "2025/08/31 12:00:00", 61, 3.906, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 129201, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 0, 201, 2, 1, 1020802, 10208, "シナツ", "2025/08/31 12:00:00", 61, 14.465, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 100101, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 0, 301, 3, 4, 1020803, 10208, "ヒヨリ", "2025/08/31 12:00:00", 61, 8.662, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 100301, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 0, 401, 3, 1, 1020804, 10208, "レイ", "2025/08/31 12:00:00", 61, 10.915, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 135802, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 0, 101, 7, 1, 1020901, 10209, "ユキノ", "2025/09/30 12:00:00", 61, 6.042, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 135903, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 0, 201, 1, 4, 1020902, 10209, "サツキ", "2025/09/30 12:00:00", 61, 9.402, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 136902, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 0, 301, 1, 8, 1020903, 10209, "ルルィ", "2025/09/30 12:00:00", 61, 8.16, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 137401, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 0, 101, 2, 3, 1021001, 10210, "カスミ", "2025/10/31 12:00:00", 61, 5, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 136001, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 0, 201, 1, 4, 1021002, 10210, "アラクネ", "2025/10/31 12:00:00", 61, 8.12, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 136202, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 0, 301, 2, 4, 1021003, 10210, "ナーナ", "2025/10/31 12:00:00", 61, 6.386, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 136402, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 0, 101, 4, 3, 1021101, 10211, "ユイ", "2025/11/30 12:00:00", 61, 7.438, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 136302, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 0, 201, 5, 1, 1021102, 10211, "ミソラ", "2025/11/30 12:00:00", 61, 8.35, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 136501, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 0, 101, 2, 1, 1021201, 10212, "シズル", "2025/12/31 12:00:00", 61, 5, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 137902, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 0, 201, 2, 1, 1021202, 10212, "リノ", "2025/12/31 12:00:00", 61, 5.25, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 106801, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 0, 301, 2, 1, 1021203, 10212, "ラビリスタ", "2025/12/31 12:00:00", 61, 7.5, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 126501, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 0, 101, 2, 1, 1021301, 10213, "ライラエル", "2026/01/31 12:00:00", 61, 8.204, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 129701, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 0, 201, 2, 1, 1021302, 10213, "ネフィ＝ネラ", "2026/01/31 12:00:00", 61, 7.176, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 133101, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 0, 301, 5, 1, 1021303, 10213, "ヴァイオレット", "2026/01/31 12:00:00", 61, 8.602, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 138101, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 0, 102, 3, 1, 1021304, 10213, "ライラエル", "2026/02/06 12:00:00", 61, 10.14, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 138201, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 0, 202, 7, 1, 1021305, 10213, "ネフィ＝ネラ", "2026/02/06 12:00:00", 61, 10.152, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 138001, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 0, 302, 3, 4, 1021306, 10213, "ヴァイオレット", "2026/02/06 12:00:00", 61, 9.688, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 138301, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 0, 401, 1, 2, 1021307, 10213, "ペコリーヌ", "2026/02/12 12:00:00", 61, 5.928, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 138702, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 0, 101, 2, 4, 1021401, 10214, "ワカナ", "2026/02/28 12:00:00", 61, 9.19, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 138802, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 0, 201, 3, 1, 1021402, 10214, "シオリ", "2026/02/28 12:00:00", 61, 8.724, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 138902, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 0, 101, 1, 4, 1021501, 10215, "グレイス", "2026/03/31 12:00:00", 61, 7.758, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 139002, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 0, 201, 4, 6, 1021502, 10215, "キョウカ", "2026/03/31 12:00:00", 61, 6.375, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 136902, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 0, 301, 1, 6, 1021503, 10215, "ルルィ", "2026/03/31 12:00:00", 61, 6.173, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 139202, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 0, 101, 2, 6, 1021601, 10216, "ミホ", "2026/04/30 12:00:00", 61, 4.202, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 139302, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 0, 201, 1, 6, 1021602, 10216, "マホ", "2026/04/30 12:00:00", 61, 2.842, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 139402, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 0, 301, 1, 4, 1021603, 10216, "エリカ", "2026/04/30 12:00:00", 61, 4.598, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 125802, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 0, 101, 3, 4, 1021701, 10217, "リリ", "2026/05/31 12:00:00", 61, 6.533, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 126102, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 0, 301, 3, 3, 1021702, 10217, "プレシア", "2026/05/31 12:00:00", 61, 5, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 126002, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 0, 201, 4, 3, 1021703, 10217, "クリア", "2026/05/31 12:00:00", 61, 5.214, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 139501, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 0, 102, 3, 1, 1021704, 10217, "リリ", "2026/05/31 12:00:00", 61, 8.781, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 139601, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 0, 202, 1, 2, 1021705, 10217, "クリア", "2026/05/31 12:00:00", 61, 6.529, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 139701, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 0, 302, 2, 3, 1021706, 10217, "プレシア", "2026/05/31 12:00:00", 61, 3.195, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 139902, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 0, 101, 3, 2, 1021801, 10218, "ルイズマリー", "2026/06/30 12:00:00", 61, 12.43, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 140001, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 0, 201, 3, 2, 1021802, 10218, "クレジッタ", "2026/06/30 12:00:00", 61, 6.35, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 140102, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 0, 101, 5, 1, 1021901, 10219, "フブキ", "2026/07/31 12:00:00", 61, 10.23, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 140201, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 0, 201, 2, 1, 1021902, 10219, "ヴァンピィ", "2026/07/31 12:00:00", 61, 5.584, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 126401, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 0, 201, 3, 6, 1022001, 10220, "クローチェ", "2026/08/31 12:00:00", 61, 2.8, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 127802, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 0, 101, 3, 4, 1022002, 10220, "ヴルム", "2026/08/31 12:00:00", 61, 8.9, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 140602, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 0, 202, 1, 2, 1022003, 10220, "クローチェ", "2026/08/31 12:00:00", 61, 4.49, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 140501, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 0, 102, 3, 1, 1022004, 10220, "ヴルム", "2026/08/31 12:00:00", 61, 9.42, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 140402, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 0, 301, 1, 4, 1022005, 10220, "リーザ", "2026/08/31 12:00:00", 61, 7, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190805, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 0, 1, 2, 1, 2000001, 2, "カリン", "2026/04/10 12:00:00", 62, 3.414, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190805, "ミッションをクリアして、\n報酬をゲットしましょう！", 0, 2, 2, 1, 2000002, 2, "カリン", "2026/04/10 12:00:00", 62, 3.099, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190805, "受け取ることができる\n報酬があるようです\n確認してみてください", 0, 3, 2, 1, 2000003, 2, "カリン", "2026/04/10 12:00:00", 63, 2.801, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190805, "報酬がもらえますよ！\nチェックしてみてください", 0, 4, 2, 2, 2000004, 2, "カリン", "2026/04/10 12:00:00", 63, 0, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190805, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 0, 5, 1, 2, 2000005, 2, "カリン", "2026/04/10 12:00:00", 64, 2.12, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190805, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 0, 6, 2, 1, 2000006, 2, "カリン", "2026/04/10 12:00:00", 64, 1.68, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES ("2030/01/01 14:59:59", 190805, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 0, 7, 1, 2, 2000007, 2, "カリン", "2026/04/10 12:00:00", 64, 2.33, -363);
